function start() {
  if (timer) return;
  timer = setInterval(() => { if (get().on()) get().sync(); else autoOn(); }, POLL_MS);
  timer.unref?.();
  if (get().on()) get().sync(); else autoOn();
}

/** Something changed here: send it up shortly. */
function changed() {
  if (!get().on()) return;
  clearTimeout(pushTimer);
  pushTimer = setTimeout(() => get().sync(), PUSH_AFTER_MS);
  pushTimer.unref?.();
}

