  start, changed, autoOn,
  /** Told when Drive sync turned itself on (main.js: the window says so). */
  onAuto: (fn) => { onAuto = fn; },
  info: () => get().info(),
  seen: () => get().seen(),
  on: () => get().on(),
  syncNow: async () => { await get().sync(); return get().info(); },
  enable: (account) => get().enable(account),
  enterCode: (code) => get().enterCode(code),
  disable: () => get().disable(),
  forget: (id) => get().forget(id),
  code: () => get().code(),
  handoff: () => get().handoff(),
  useCodec, SCOPE, PREFIX, POLL_MS, googleDrive,
