const TIME_PATTERN = new RegExp(
  PREFIX + String.raw`\b(\d{1,2})(?::([0-5]\d))?\s*([ap])\.?\s*m\.?(?![a-z])|` + PREFIX + String.raw`\b([01]?\d|2[0-3]):([0-5]\d)\b`, 'i');

